"use client";
import{useCallback,useEffect,useMemo,useState}from"react";import Link from"next/link";import{AppShell}from"../ui/app-shell";import{getSupabaseBrowserClient}from"../../lib/supabase/client";import{usePlayerData}from"../../lib/use-player-data";import"../players.css";
type Overview={player_id:string;display_name:string;email:string;programme_status:string;current_week:number;adherence_percent:number;safety_flags:number;stop_flags:number;incomplete_sessions:number;unreviewed_sessions:number;outstanding_retests:number;overdue_retests:number;draft_diagnostics:number;last_round:string|null;last_trackman:string|null;last_session:string|null;priority_score:number};type Event={occurred_at:string;kind:string;title:string;status:string;detail:string};
const date=(value:string|null)=>value?new Date(value).toLocaleDateString(undefined,{day:"numeric",month:"short",year:"numeric"}):"No activity";
export default function PlayerOverview(){const{profile}=usePlayerData();const canCoach=profile?.role==="coach"||profile?.role==="admin";const[players,setPlayers]=useState<Overview[]>([]);const[selectedId,setSelectedId]=useState("");const[history,setHistory]=useState<Event[]>([]);const[search,setSearch]=useState("");const[filter,setFilter]=useState<"attention"|"all">("attention");const[message,setMessage]=useState("");
 const load=useCallback(async()=>{const sb=getSupabaseBrowserClient();if(!sb||!canCoach)return;const{data,error}=await sb.rpc("coach_player_overview");if(error){setMessage(error.message);return}const rows=(data||[])as Overview[];setPlayers(rows);setSelectedId(value=>value&&rows.some(item=>item.player_id===value)?value:rows[0]?.player_id||"")},[canCoach]);const loadHistory=useCallback(async()=>{const sb=getSupabaseBrowserClient();if(!sb||!selectedId)return;const{data,error}=await sb.rpc("coach_player_history",{target_player:selectedId});if(error)setMessage(error.message);else setHistory((data||[])as Event[])},[selectedId]);useEffect(()=>{const timer=setTimeout(()=>void load(),0);return()=>clearTimeout(timer)},[load]);useEffect(()=>{const timer=setTimeout(()=>void loadHistory(),0);return()=>clearTimeout(timer)},[loadHistory]);
 const totals=useMemo(()=>({attention:players.filter(item=>item.priority_score>0).length,stop:players.filter(item=>item.stop_flags>0).length,retests:players.reduce((sum,item)=>sum+Number(item.outstanding_retests),0),reviews:players.reduce((sum,item)=>sum+Number(item.unreviewed_sessions)+Number(item.draft_diagnostics),0)}),[players]);const visible=players.filter(item=>(filter==="all"||item.priority_score>0)&&`${item.display_name} ${item.email}`.toLowerCase().includes(search.toLowerCase()));const selected=players.find(item=>item.player_id===selectedId);
 if(profile&&!canCoach)return <AppShell active="players"><div className="empty-state"><h2>Coach access required</h2><p>The player overview is available only to approved coaches.</p></div></AppShell>;
 return <AppShell active="players"><header className="page-heading"><div><p className="eyebrow">Package 7G.4 · Coach overview</p><h1>Know who needs you next.</h1><p>One roster combining safety, adherence, outstanding reviews, retests and recent player activity.</p></div></header>{message&&<div className="success-banner">{message}</div>}<section className="roster-metrics"><div><strong>{players.length}</strong><span>linked players</span></div><div><strong>{totals.attention}</strong><span>requiring attention</span></div><div className={totals.stop?"urgent":""}><strong>{totals.stop}</strong><span>stop and review</span></div><div><strong>{totals.retests}</strong><span>outstanding retests</span></div><div><strong>{totals.reviews}</strong><span>reviews to complete</span></div></section><section className="roster-toolbar"><input value={search} onChange={event=>setSearch(event.target.value)} placeholder="Search players" aria-label="Search players"/><div><button className={filter==="attention"?"active":""} onClick={()=>setFilter("attention")}>Attention</button><button className={filter==="all"?"active":""} onClick={()=>setFilter("all")}>All players</button></div></section>
 <div className="roster-layout"><section className="roster-list">{visible.map(item=><button className={`${selectedId===item.player_id?"active":""} ${item.stop_flags?"urgent":""}`} onClick={()=>setSelectedId(item.player_id)} key={item.player_id}><header><span className="roster-initials">{item.display_name.split(/\s|@/).filter(Boolean).slice(0,2).map(part=>part[0]).join("")}</span><div><strong>{item.display_name}</strong><small>{item.email}</small></div><b>{item.priority_score}</b></header><div className="roster-flags">{item.stop_flags>0&&<span className="stop">Stop/review {item.stop_flags}</span>}{item.safety_flags>item.stop_flags&&<span>Monitor {item.safety_flags-item.stop_flags}</span>}{item.overdue_retests>0&&<span>Overdue retest {item.overdue_retests}</span>}{item.unreviewed_sessions>0&&<span>Feedback {item.unreviewed_sessions}</span>}{item.draft_diagnostics>0&&<span>Draft review {item.draft_diagnostics}</span>}{item.priority_score===0&&<span className="clear">No current flags</span>}</div><footer><span>Week {item.current_week||"—"}</span><span>{item.adherence_percent||0}% adherence</span><span>TrackMan {date(item.last_trackman)}</span></footer></button>)}{!visible.length&&<div className="empty-state compact"><h2>No players match</h2><p>Change the search or show all linked players.</p></div>}</section><aside className="player-overview-detail">{selected?<><header><div><p className="eyebrow">Selected player</p><h2>{selected.display_name}</h2><span>{selected.email}</span></div><b className={selected.priority_score?"attention":"clear"}>{selected.priority_score?`Priority ${selected.priority_score}`:"Clear"}</b></header><div className="player-status-grid"><div><span>Programme</span><strong>{selected.programme_status}</strong><small>Week {selected.current_week||"—"}</small></div><div><span>Adherence</span><strong>{selected.adherence_percent||0}%</strong><small>Current week</small></div><div><span>Retests</span><strong>{selected.outstanding_retests}</strong><small>{selected.overdue_retests} overdue</small></div><div><span>Incomplete</span><strong>{selected.incomplete_sessions}</strong><small>Last 21 days</small></div></div><div className="player-action-links"><Link href="/coach">Evidence</Link><Link href="/programme">Programme</Link><Link href="/progress">Progress</Link><Link href="/trackman/diagnose">TrackMan</Link></div><section className="recent-activity"><div className="section-heading"><div><p className="eyebrow">Searchable history</p><h2>Recent activity</h2></div></div>{history.map((event,index)=><article key={`${event.occurred_at}-${event.kind}-${index}`}><span className={`event-kind ${event.kind}`}>{event.kind}</span><div><strong>{event.title}</strong><p>{event.detail}</p><small>{date(event.occurred_at)} · {event.status.replaceAll("_"," ")}</small></div></article>)}{!history.length&&<p className="empty-copy">No recorded activity yet.</p>}</section></>:<div className="empty-state compact"><h2>Select a player</h2><p>Choose a roster entry to inspect their current state and history.</p></div>}</aside></div></AppShell>}
